parent.child = child;
child.parent = parent;   // cycle
parent = null;
child = null;            // toy refcounting: both counts still == 1

function liveSet(heap, roots) {
  // BUG: marks anything with an incoming reference as live (refcount-style),
  // so an unrooted cycle x<->y survives.
  const incoming = {};
  for (const id of Object.keys(heap)) incoming[id] = 0;
  for (const id of Object.keys(heap)) {
    for (const ref of heap[id]) incoming[ref] = (incoming[ref] || 0) + 1;
  }
  const live = new Set(roots);
  for (const id of Object.keys(heap)) {
    if (incoming[id] > 0) live.add(id);
  }
  return live;
}

