const meta = new Map();      // node -> { lastSeen, payload }
const listeners = [];

function track(node, payload) {
  meta.set(node, { lastSeen: Date.now(), payload });
  const onClick = () => highlight(node);
  node.addEventListener('click', onClick);
  listeners.push(onClick);   // keep a ref so we can remove later (we never do)
}

function getMeta(node) {
  return meta.get(node);
}

